<div class="page-heading"><div><a class="back-link" href="<?= site_url('permohonan') ?>">← Semua permohonan</a><div class="eyebrow">Detail permohonan</div><h1><?= e($request->request_no) ?></h1><p><?= $request->service_type === 'tera_ulang' ? 'Tera ulang' : 'Tera' ?> · <?= e($request->submitted_at) ?> · <?= e($request->full_name) ?></p></div><a class="button outline" href="<?= site_url('permohonan/' . $request->id . '/bukti') ?>">↓ Bukti permohonan PDF</a></div>
<div class="detail-grid"><div><section class="card detail-card"><div class="section-heading compact"><div><div class="eyebrow">Pelacakan</div><h2>Status per unit</h2></div><span class="badge <?= status_class($request->request_status) ?>"><?= e(status_label($request->request_status)) ?></span></div>
<?php foreach ($items as $item): ?><article class="unit-row"><div class="unit-head"><div><strong>Unit #<?= (int) $item->unit_sequence ?> · <?= e($item->uttp_name) ?></strong><small><?= e($item->owner_name) ?><?= $item->brand ? ' · ' . e($item->brand) : '' ?><?= $item->capacity ? ' · ' . e($item->capacity) : '' ?></small></div><span class="badge <?= status_class($item->item_status) ?>"><?= e(status_label($item->item_status)) ?></span></div><div class="progress"><span style="width:<?= $item->item_status === 'completed' ? 100 : (in_array($item->item_status, array('review','testing')) ? 72 : (in_array($item->item_status, array('scheduled')) ? 50 : 25)) ?>%"></span></div>
<?php foreach ($documents as $doc): if ($doc->document_type === 'skhp' && (int) $doc->request_item_id === (int) $item->id && $item->item_status === 'completed'): ?><a class="download-link" href="<?= site_url('dokumen/' . $doc->id) ?>">↓ Unduh SKHP</a><?php endif; endforeach; ?></article><?php endforeach; ?></section>
<section class="card detail-card"><h2>Riwayat proses</h2><?php foreach ($history as $h): if ($h->visibility !== 'applicant') continue; ?><div class="timeline-row"><span class="timeline-dot"></span><div><strong>Unit #<?= (int) array_search($h->request_item_id, array_column($items, 'id')) + 1 ?> · <?= e(status_label($h->to_status)) ?></strong><small><?= e($h->created_at) ?><?= $h->note ? ' · ' . e($h->note) : '' ?></small></div></div><?php endforeach; ?></section></div>
<aside><section class="card detail-card"><h2>Ringkasan</h2><dl class="summary"><div><dt>Pemohon</dt><dd><?= e($request->full_name) ?></dd></div><div><dt>Alamat layanan</dt><dd><?= e($request->service_address) ?></dd></div><div><dt>Jumlah unit</dt><dd><?= count($items) ?></dd></div></dl></section>
<section class="card detail-card"><h2>Dokumen</h2><?php foreach ($documents as $doc): if ($doc->document_type !== 'application_letter') continue; ?><a class="document-link" href="<?= site_url('dokumen/' . $doc->id) ?>">↓ Surat permohonan</a><?php endforeach; ?></section>
<?php if ($needs_revision): ?><section class="card detail-card"><h2>Perbaiki berkas</h2><p class="muted">Unggah surat permohonan PDF yang telah diperbaiki.</p><form method="post" enctype="multipart/form-data" action="<?= site_url('permohonan/' . $request->id . '/perbaiki') ?>"><?= form_hidden($this->security->get_csrf_token_name(), $this->security->get_csrf_hash()) ?><input type="file" name="application_letter" accept="application/pdf,.pdf" required><button class="button primary full" type="submit">Kirim perbaikan</button></form></section><?php endif; ?>
<?php if ($request->request_status === 'completed' && !$feedback): ?><section class="card detail-card"><h2>Kritik dan saran</h2><form method="post" action="<?= site_url('permohonan/' . $request->id . '/umpan-balik') ?>"><?= form_hidden($this->security->get_csrf_token_name(), $this->security->get_csrf_hash()) ?><label>Nilai layanan<select name="rating" required><option value="">Pilih nilai</option><?php for ($i=1;$i<=5;$i++): ?><option value="<?= $i ?>"><?= $i ?> bintang</option><?php endfor; ?></select></label><label>Masukan<textarea name="comment" rows="3" maxlength="2000"></textarea></label><button class="button primary full" type="submit">Kirim masukan</button></form></section><?php endif; ?>
</aside></div>
